const items = [{"name":"Banan","filename":"banan.jpg","data":""},{"name":"Malina","filename":"malina.jpg","data":""},{"name":"Negr","filename":"negr.jpg","data":""},{"name":"Oq qora","filename":"oq-qora.jpg","data":""},{"name":"Ptichi malako","filename":"ptichi-malako.jpg","data":""},{"name":"Qora mahrovi","filename":"qora-mahrovi.jpg","data":""},{"name":"Sharik pirojniy","filename":"sharik-pirojniy.jpg","data":""},{"name":"Shkaladniy tvarojnik","filename":"shkaladniy-tvarojnik.jpg","data":""}];

const allCategories = await base44.entities.Category.list();
const category = allCategories.find((c) => String(c.name).trim().toLowerCase() === "18 somlik");
if (!category) throw new Error("18 somlik category not found");

const allProducts = await base44.entities.Product.list();
const shops = (await base44.entities.Shop.list()).filter((s) => s.active === true && s.location_type === "shop" && s.allows_pos !== false);
const allStocks = await base44.entities.ProductStock.list();

const result = [];
for (const item of items) {
  const bytes = Uint8Array.from(atob(item.data), (c) => c.charCodeAt(0));
  const file = new File([bytes], item.filename, { type: "image/jpeg" });
  const uploaded = await base44.integrations.Core.UploadFile({ file });
  const imageUrl = uploaded.file_url;

  let product = allProducts.find((p) =>
    String(p.name || "").trim().toLowerCase() === item.name.toLowerCase() &&
    (p.category_id === category.id || String(p.category_name || "").trim().toLowerCase() === "18 somlik")
  );

  const payload = {
    name: item.name,
    price: 18000,
    category_id: category.id,
    category_name: category.name,
    image_url: imageUrl,
    active: true,
    archived: false,
    source_type: "central_produced",
    production_unit: "piece",
    pieces_per_sheet: 1,
    sheet_price: 0,
    stock_unit: "piece",
    track_stock: true,
    is_favorite: false,
  };

  if (product) {
    product = await base44.entities.Product.update(product.id, payload);
  } else {
    product = await base44.entities.Product.create(payload);
    allProducts.push(product);
  }

  const stockCreated = [];
  for (const shop of shops) {
    const exists = allStocks.find((s) => s.product_id === product.id && s.location_id === shop.id);
    if (!exists) {
      const stock = await base44.entities.ProductStock.create({
        location_id: shop.id,
        location_name: shop.name,
        product_id: product.id,
        product_name: product.name,
        unit: "piece",
        quantity: 0,
        low_stock_level: 0,
        updated_at: new Date().toISOString(),
      });
      allStocks.push(stock);
      stockCreated.push(shop.name);
    }
  }

  result.push({ name: product.name, id: product.id, image_url: product.image_url, stock_created_for: stockCreated });
}
console.log(JSON.stringify({ category: category.name, shops: shops.map(s => s.name), products: result }, null, 2));